entries[10604] = { ["name"] = "Schematic: Mithril Heavy-bore Rifle", ["text"] = "Requires Engineering (220)\nUse: Teaches you how to make a Mithril Heavy-bore Rifle.\nMithril Heavy-bore Rifle\nBinds when equipped\nRanged Gun\n41 - 76 Damage Speed 2.90\n(20.17 damage per second)\nDurability 65 / 65\nRequires Level 39\nEquip: +14 ranged Attack Power.\nRequires Mithril Tube (2), Unstable Trigger , Heavy Stock , Mithril Bar (6), Citrine (2)" }
entries[10605] = { ["name"] = "Schematic: Spellpower Goggles Xtreme", ["text"] = "Requires Engineering (225)\nUse: Teaches you how to make Spellpower Goggles Xtreme.\nSpellpower Goggles Xtreme\nBinds when equipped\nHead Cloth\n46 Armor\nDurability 45 / 45\nRequires Engineering (215)\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\nRequires Thick Leather (4), Star Ruby (2)" }
entries[10606] = { ["name"] = "Schematic: Parachute Cloak", ["text"] = "Requires Engineering (225)\nUse: Teaches you how to make a Parachute Cloak.\nParachute Cloak\nBinds when equipped\nBack\n30 Armor\n+8 Agility\nRequires Engineering (225)\nUse: Reduces your fall speed for 10 sec. (30 Min Cooldown)\nRequires Bolt of Mageweave (4), Shadow Silk (2), Unstable Trigger , Solid Blasting Powder (4)" }
entries[10607] = { ["name"] = "Schematic: Deepdive Helmet", ["text"] = "Requires Engineering (230)\nUse: Teaches you how to make a Deepdive Helmet.\nDeepdive Helmet\nBinds when equipped\nHead Cloth\n49 Armor\n+15 Stamina\nDurability 45 / 45\nRequires Engineering (230)\nEquip: Allows underwater breathing.\nRequires Mithril Bar (8), Mithril Casing , Truesilver Bar , Tigerseye (4), Malachite (4)" }
entries[10608] = { ["name"] = "Schematic: Sniper Scope", ["text"] = "Requires Engineering (240)\nUse: Teaches you how to make a Sniper Scope.\nSniper Scope\nRequires Level 40\nUse: Attaches a permanent scope to a bow or gun that increases its damage by 7.\nRequires Mithril Tube , Star Ruby , Truesilver Bar (2)" }
entries[10609] = { ["name"] = "Schematic: Mithril Mechanical Dragonling", ["text"] = "Requires Engineering (250)\nUse: Teaches you how to make a Mithril Mechanical Dragonling.\nMithril Mechanical Dragonling\nBinds when equipped\nUnique\nTrinket\nRequires Level 40\nRequires Engineering (250)\nUse: Activates your Mithril Mechanical Dragonling to fight for you for 1 min. It requires an hour to cool down before it can be used again. (1 Hour Cooldown)\nRequires Mithril Bar (14), Heart of Fire (4), Truesilver Bar (4), Inlaid Mithril Cylinder (2), Goblin Rocket Fuel (2), Star Ruby (2)" }
